import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        D = int(next(iterator))

        snakes = []
        for _ in range(N):
            t = int(next(iterator))
            l = int(next(iterator))
            snakes.append((t, l))

    except StopIteration:
        return

    # Process for each k from 1 to D
    for k in range(1, D + 1):
        max_weight = 0
        for t, l in snakes:
            current_weight = t * (l + k)
            if current_weight > max_weight:
                max_weight = current_weight
        print(max_weight)

if __name__ == '__main__':
    solve()

import sys

def solve():
    # Read input from stdin
    try:
        line = sys.stdin.read().split()
        if not line:
            return
        A = [int(x) for x in line]
    except ValueError:
        return

    target = [1, 2, 3, 4, 5]

    # Check if A can be sorted by exactly one adjacent swap
    # Since the length is fixed at 5, we can just try all 4 possible adjacent swaps.

    found = False
    for i in range(4):
        # Create a copy to simulate the swap
        temp = A[:]
        # Swap adjacent elements at index i and i+1
        temp[i], temp[i+1] = temp[i+1], temp[i]

        # Check if the result matches the sorted sequence
        if temp == target:
            found = True
            break

    if found:
        print("Yes")
    else:
        print("No")

if __name__ == '__main__':
    solve()
